) AS p(org_name, post_title, vacancy_count, deadline, official_notification_url)
JOIN organization_mapping om ON p.org_name = om.official_name
WHERE p.post_title IS NOT NULL
  AND p.vacancy_count > 0
  AND p.deadline IS NOT NULL;

-- Post-ingest validation
SELECT
  COUNT(*) as total_posts,
  COUNT(DISTINCT organization_id) as unique_organizations,
  MIN(deadline) as earliest_deadline,
  MAX(deadline) as latest_deadline,
  SUM(vacancy_count) as total_vacancies
FROM posts
WHERE is_official_source = true;

